True from collections import Counter


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color, stack = grid[r][c], [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                rr, cc = stack.pop()
                cells.add((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            result.append((color, cells))
    return result


def _bbox(cells):
    return (min(r for r, c in cells), min(c for r, c in cells),
            max(r for r, c in cells), max(c for r, c in cells))


def _shape(cells):
    r0, c0, _, _ = _bbox(cells)
    return frozenset((r-r0, c-c0) for r, c in cells)


def _corner(cells):
    r0, c0, r1, c1 = _bbox(cells)
    if r0 == r1 or c0 == c1:
        return None
    for r, c in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
        if cells == ({(r, x) for x in range(c0, c1 + 1)}
                     | {(y, c) for y in range(r0, r1 + 1)}):
            return r, c
    return None


def _inside(box, outer):
    return (outer[0] <= box[0] and outer[1] <= box[1]
            and box[2] <= outer[2] and box[3] <= outer[3])


def _disjoint(a, b):
    return a[2] < b[0] or a[0] > b[2] or a[3] < b[1] or a[1] > b[3]


def _quadrant(box, corner):
    r0, c0, r1, c1 = box
    cr, cc = corner
    return (-1 if (r0+r1)/2 < cr else 1,
            -1 if (c0+c1)/2 < cc else 1)


def _is_subshape(candidate, source):
    p, q = _shape(source), _shape(candidate)
    if len(q) >= len(p):
        return False
    for dr in range(-max(r for r, c in q), max(r for r, c in p) + 1):
        for dc in range(-max(c for r, c in q), max(c for r, c in p) + 1):
            if {(dr+r, dc+c) for r, c in q} <= p:
                return True
    return False


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objects = [(color, cells, _bbox(cells)) for color, cells in _components(grid)
               if color != background]
    markers = [(obj, _corner(obj[1])) for obj in objects]
    markers = [(obj, corner) for obj, corner in markers if corner is not None]
    if not markers:
        return out
    (marker_color, marker_cells, marker_box), corner = max(markers, key=lambda x: len(x[0][1]))
    inside = [obj for obj in objects
              if obj[1] != marker_cells and _inside(obj[2], marker_box)]
    outside = [obj for obj in objects
               if obj[1] != marker_cells and _disjoint(obj[2], marker_box)]
    targets = set()
    for source_color, source_cells, source_box in inside:
        pattern = _shape(source_cells)
        exact = [obj for obj in outside if _shape(obj[1]) == pattern]
        if len(exact) != 1:
            continue
        target = exact[0]
        source_q, target_q = _quadrant(source_box, corner), _quadrant(target[2], corner)
        if len(pattern) > 1 and target_q == (-source_q[0], -source_q[1]):
            desired_q = (source_q[0], -source_q[1])
            fragments = [obj for obj in outside if obj[0] == source_color
                         and _is_subshape(obj[1], source_cells)
                         and _quadrant(obj[2], corner) == desired_q]
            if fragments:
                largest = max(len(obj[1]) for obj in fragments)
                best = [obj for obj in fragments if len(obj[1]) == largest]
                if len(best) == 1:
                    targets.update(best[0][1])
                    continue
        targets.update(target[1])
    for r, c in targets:
        out[r][c] = marker_color
    return out

